{"kind": "content", "icon": "✍️", "head": "स्वर लिखने के चिह्न", "points": ["भातखंडे पद्धति", "कोमल – स्वर के नीचे आड़ी रेखा (रे॒)", "तीव्र म – ऊपर खड़ी रेखा (म॑)", "मंद्र सप्तक – नीचे बिंदी (ऩि)", "तार सप्तक – ऊपर बिंदी (सां)"], "say": "स्वरों को लिखने के लिए पंडित विष्णु नारायण भातखंडे की पद्धति में कुछ चिह्न हैं। कोमल स्वर के नीचे एक छोटी आड़ी रेखा लगाते हैं। तीव्र म के ऊपर एक छोटी खड़ी रेखा लगाते हैं। नीचे वाले सप्तक के स्वर के नीचे बिंदी, और ऊपर वाले सप्तक के स्वर के ऊपर बिंदी लगाई जाती है, जैसे ऊपर वाला सा बिंदी के साथ सां लिखा जाता है। इन चिह्नों से हम किसी भी गीत की धुन काग़ज़ पर लिख सकते हैं।", "img": "mu_notes.jpg", "cap": "स्वरलिपि · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "📶", "head": "सप्तक", "points": ["सात स्वरों का समूह", "मंद्र सप्तक – नीचा (हृदय से)", "मध्य सप्तक – सामान्य (कंठ से)", "तार सप्तक – ऊँचा (सिर/तालु से)", "तार सा की आवृत्ति = मध्य सा की दोगुनी"], "say": "सा से नि तक सात स्वरों के समूह को सप्तक कहते हैं। सप्तक तीन हैं। मंद्र सप्तक, जो नीचा होता है और जिसकी आवाज़ हृदय से निकलती महसूस होती है। मध्य सप्तक, जिसमें हम सामान्य बातचीत और ज़्यादातर गायन करते हैं, आवाज़ कंठ से। और तार सप्तक, जो ऊँचा होता है, आवाज़ सिर से निकलती महसूस होती है। एक रोचक तथ्य, तार सप्तक के सा की आवृत्ति मध्य सप्तक के सा की ठीक दोगुनी होती है। अच्छे गायक तीनों सप्तकों में गा सकते हैं।"},
{"kind": "content", "icon": "🎹", "head": "आरोह और अवरोह", "points": ["आरोह – नीचे से ऊपर: सा रे ग म प ध नि सां", "अवरोह – ऊपर से नीचे: सां नि ध प म ग रे सा", "सीढ़ी चढ़ना-उतरना", "हर राग का अपना आरोह-अवरोह", "रोज़ अभ्यास – स्वर पक्के"], "say": "स्वरों को नीचे से ऊपर की ओर गाना आरोह कहलाता है, सा रे ग म प ध नि सां, जैसे सीढ़ी चढ़ना। और ऊपर से नीचे की ओर गाना अवरोह कहलाता है, सां नि ध प म ग रे सा, जैसे सीढ़ी उतरना। हर राग का अपना अलग आरोह अवरोह होता है, जो हम अगले अध्याय में पढ़ेंगे। रोज़ सुबह आरोह अवरोह का अभ्यास करने से स्वर पक्के होते हैं और आवाज़ सुरीली बनती है। इसे स्वर साधना या रियाज़ कहते हैं।"},
{"kind": "content", "icon": "🌅", "head": "अलंकार: स्वर अभ्यास", "points": ["स्वरों के नियमित क्रम", "सारे रेग गम मप पध धनि निसां", "सारेग रेगम गमप …", "आवाज़ में लचीलापन", "रोज़ 15 मिनट"], "say": "स्वरों को एक नियमित क्रम में गाने को अलंकार या पलटा कहते हैं। जैसे पहला अलंकार, सारे, रेग, गम, मप, पध, धनि, निसां। दूसरा, सारेग, रेगम, गमप, मपध, पधनि, धनिसां। उल्टा भी गाया जाता है। अलंकार से आवाज़ में लचीलापन आता है, स्वरों पर पकड़ बनती है, और गला खुलता है। जैसे खिलाड़ी रोज़ व्यायाम करता है, वैसे ही गायक रोज़ अलंकार गाता है। सुबह पंद्रह मिनट अलंकार का रियाज़ कीजिए।"},
{"kind": "table", "icon": "📚", "head": "याद रखें", "eq": "शब्द – अर्थ", "rows": [["शब्द", "अर्थ"], ["नाद", "संगीतोपयोगी मधुर ध्वनि"], ["श्रुति", "सबसे छोटी सुनने योग्य दूरी (22)"], ["सप्तक", "सात स्वरों का समूह"], ["अचल स्वर", "सा, प"], ["कोमल / तीव्र", "नीचे / ऊपर खिसका स्वर"], ["अलंकार", "स्वरों का नियमित अभ्यास क्रम"]], "say": "याद रखें। नाद, संगीत के काम आने वाली मधुर ध्वनि। श्रुति, सबसे छोटी सुनने योग्य दूरी, कुल बाईस। सप्तक, सात स्वरों का समूह। अचल स्वर, सा और प। कोमल यानी नीचे और तीव्र यानी ऊपर खिसका स्वर। अलंकार, स्वरों का नियमित अभ्यास क्रम।"},
{"kind": "content", "icon": "📋", "head": "सार", "points": ["संगीत = गायन + वादन + नृत्य", "आहत और अनाहत नाद", "22 श्रुतियाँ, 7 स्वर, 12 स्वर", "अचल: सा, प; कोमल: रे ग ध नि; तीव्र: म", "मंद्र, मध्य, तार सप्तक; आरोह-अवरोह"], "say": "सार। संगीत गायन, वादन और नृत्य का मेल है। नाद आहत और अनाहत होता है। एक सप्तक में बाईस श्रुतियाँ और सात स्वर हैं, और कोमल तीव्र मिलाकर बारह स्वर। सा और प अचल हैं, रे ग ध नि कोमल हो सकते हैं और म तीव्र। तीन सप्तक हैं, मंद्र, मध्य और तार। स्वरों का चढ़ना आरोह और उतरना अवरोह है।"},
{"kind": "content", "icon": "🎤", "head": "आवाज़ कैसे बनती है?", "points": ["फेफड़ों से हवा", "कंठ में स्वर-तंतु (vocal cords) काँपते", "तनाव ज़्यादा = ऊँचा स्वर", "मुँह, नाक, गला – गूँज", "साँस पर नियंत्रण ज़रूरी"], "say": "हमारी आवाज़ कैसे बनती है? फेफड़ों से हवा निकलकर गले में स्वर तंतुओं से टकराती है। स्वर तंतु दो पतली झिल्लियाँ हैं, जो हवा लगने पर काँपती हैं, और यही कंपन आवाज़ बनाता है। जब स्वर तंतु ज़्यादा तने होते हैं, तो कंपन तेज़ होता है और स्वर ऊँचा निकलता है। फिर मुँह, नाक और गले की ख़ाली जगहों में आवाज़ गूँजकर सुंदर बनती है। इसलिए गायन में साँस पर नियंत्रण बहुत ज़रूरी है। गहरी साँस लेने का अभ्यास कीजिए।", "ext": 1, "img": "mu_sing.jpg", "cap": "गायन · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "🧘", "head": "गले की देखभाल", "points": ["बहुत ठंडा-खट्टा कम", "गुनगुना पानी, शहद-अदरक", "चिल्लाना नहीं", "सुबह खुली हवा में रियाज़", "पर्याप्त नींद"], "say": "गायक के लिए गला उसका वाद्य है, इसलिए उसकी देखभाल ज़रूरी है। बहुत ठंडी चीज़ें, बर्फ़ का पानी और बहुत खट्टी चीज़ें कम खाइए। गुनगुना पानी पीजिए, सर्दी में शहद और अदरक लाभदायक है। ज़ोर से चिल्लाने से स्वर तंतु थक जाते हैं, इसलिए चिल्लाने से बचिए। सुबह खुली हवा में रियाज़ सबसे अच्छा माना जाता है, जिसे खरज का रियाज़ भी कहते हैं, यानी नीचे के सा पर लंबा स्वर लगाना। और भरपूर नींद लीजिए।", "ext": 1},
{"kind": "content", "icon": "🎚️", "head": "तानपूरा और सा", "points": ["तानपूरा – सुर का आधार", "चार तार: प सा सा सा (मंद्र)", "लगातार गूँज – स्वर पकड़ने में मदद", "अपना 'सा' चुनें – आवाज़ के अनुसार", "आज मोबाइल में तानपूरा ऐप"], "say": "गायन में तानपूरा बहुत ज़रूरी वाद्य है। इसमें आमतौर पर चार तार होते हैं, जो मंद्र प, सा, सा और मंद्र सा में मिलाए जाते हैं। तानपूरे की लगातार गूँज गायक को सही स्वर पकड़ने में मदद करती है, जैसे अँधेरे में दीया रास्ता दिखाता है। हर व्यक्ति का सा उसकी आवाज़ के अनुसार अलग होता है, किसी का ऊँचा, किसी का नीचा। आज मोबाइल पर मुफ़्त तानपूरा ऐप भी मिलते हैं, जिनसे घर पर अभ्यास कर सकते हैं।", "ext": 1, "img": "mu_harmo.jpg", "cap": "कुंजी वाला वाद्य · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "🌍", "head": "पश्चिमी संगीत से तुलना", "points": ["Do Re Mi Fa So La Ti", "C D E F G A B", "सा = Do (कोई भी चुना जा सकता है)", "पश्चिम – हारमनी (एक साथ कई स्वर)", "भारत – मेलोडी (एक के बाद एक स्वर), राग"], "say": "पश्चिमी संगीत में भी सात स्वर होते हैं, जिन्हें डो, रे, मी, फ़ा, सो, ला, टी कहते हैं, या अंग्रेज़ी अक्षरों में सी, डी, ई, एफ़, जी, ए, बी। हमारा सा उनके डो जैसा है। एक बड़ा अंतर यह है कि पश्चिमी संगीत में हारमनी पर ज़ोर है, यानी एक साथ कई स्वर बजाना। भारतीय संगीत में मेलोडी पर ज़ोर है, यानी एक के बाद एक स्वर, और राग की सुंदर व्यवस्था। दोनों अपनी जगह सुंदर हैं।", "ext": 1, "img": "mu_piano.jpg", "cap": "स्वरलिपि और पियानो · फ़ोटो: PxHere (CC0)"},
{"kind": "content", "icon": "🔁", "head": "एक बार फिर दोहराइए", "points": ["सामवेद, नाट्यशास्त्र, संगीत रत्नाकर", "आहत-अनाहत नाद; नाद के 3 गुण", "22 श्रुति, 7 स्वर, 12 स्वर", "अचल सा-प; कोमल रे ग ध नि; तीव्र म", "मंद्र-मध्य-तार; आरोह-अवरोह; अलंकार"], "say": "पूरा अध्याय दोहराइए। सामवेद, नाट्यशास्त्र और संगीत रत्नाकर। आहत और अनाहत नाद, और नाद के तीन गुण। बाईस श्रुति, सात स्वर, बारह स्वर। अचल सा और प, कोमल रे ग ध नि, तीव्र म। मंद्र, मध्य, तार सप्तक, आरोह अवरोह और अलंकार।", "ext": 1},
